insert into public.activities (code, title, active)
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q01', 'AULA01-SISTNUM', 1, 'Conceitual', 'Quais símbolos podem aparecer em um número binário?', '["0 e 1", "0 a 7", "0 a 9", "0 a 9 e A a F"]'::jsonb, '0 e 1', 'O sistema binário é de base 2 e utiliza apenas os símbolos 0 e 1.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q02', 'AULA01-SISTNUM', 2, 'Conceitual', 'No sistema hexadecimal, qual é o valor decimal do símbolo F?', '["10", "14", "15", "16"]'::jsonb, '15', 'No hexadecimal, A=10, B=11, C=12, D=13, E=14 e F=15.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q03', 'AULA01-SISTNUM', 3, 'Conceitual', 'No número decimal 410, por que o algarismo 4 representa 400?', '["Porque 4 sempre vale 400", "Porque está na posição correspondente a 10²", "Porque 410 é um número binário", "Porque a base decimal é 4"]'::jsonb, 'Porque está na posição correspondente a 10²', 'Na notação posicional decimal: 410 = 4×10² + 1×10¹ + 0×10⁰.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q04', 'AULA01-SISTNUM', 4, 'Conceitual', 'Quantos bits correspondem exatamente a um dígito hexadecimal?', '["2", "3", "4", "8"]'::jsonb, '4', 'Como 16 = 2⁴, cada dígito hexadecimal representa exatamente 4 bits.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q05', 'AULA01-SISTNUM', 5, 'Conceitual', 'Qual é o valor decimal de 10₂?', '["1", "2", "10", "16"]'::jsonb, '2', '10₂ = 1×2¹ + 0×2⁰ = 2₁₀.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
