insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q15', 'AULA01-SISTNUM', 15, 'Médio', 'Qual é a representação binária de 3A₁₆ em grupos de 4 bits?', '["0011 1010", "0011 1100", "1010 0011", "1110 0011"]'::jsonb, '0011 1010', '3₁₆ = 0011₂ e A₁₆ = 1010₂. Logo, 3A₁₆ = 0011 1010₂.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
