insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q19', 'AULA01-SISTNUM', 19, 'Difícil', 'Converta 10110110₂ para hexadecimal.', '["A6₁₆", "B6₁₆", "B5₁₆", "C6₁₆"]'::jsonb, 'B6₁₆', '1011 0110 → B 6. Portanto, 10110110₂ = B6₁₆.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
