insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q24', 'AULA01-SISTNUM', 24, 'Desafiador', 'Qual das equivalências abaixo está INCORRETA?', '["255₁₀ = 11111111₂ = FF₁₆", "64₁₀ = 1000000₂ = 40₁₆", "31₁₀ = 11111₂ = 1F₁₆", "26₁₀ = 11010₂ = 1B₁₆"]'::jsonb, '26₁₀ = 11010₂ = 1B₁₆', '26₁₀ = 11010₂, mas em hexadecimal é 1A₁₆, e não 1B₁₆.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
insert into public.questions (id, activity_code, position, level, prompt, options, correct_answer, explanation, active) values ('Q25', 'AULA01-SISTNUM', 25, 'Desafiador', 'O valor decimal 2748 deve ser representado em binário e hexadecimal. Qual par está correto?', '["1010 1011 1100₂ e ABC₁₆", "1010 1011 1101₂ e ABD₁₆", "1011 1010 1100₂ e BAC₁₆", "1010 1100 1011₂ e ACB₁₆"]'::jsonb, '1010 1011 1100₂ e ABC₁₆', 'ABC₁₆ = 10×16² + 11×16 + 12 = 2748, e A B C → 1010 1011 1100₂.', true) on conflict (id) do update set activity_code=excluded.activity_code, position=excluded.position, level=excluded.level, prompt=excluded.prompt, options=excluded.options, correct_answer=excluded.correct_answer, explanation=excluded.explanation, active=excluded.active;
